def risk_score(likelihood, impact):
    for x in (likelihood, impact):
        if not isinstance(x, int) or isinstance(x, bool) or not 1 <= x <= 5:
            raise ValueError('likelihood and impact must be integers from 1 to 5')
    score = likelihood * impact
    level = 'LOW' if score <= 5 else 'MEDIUM' if score <= 12 else 'HIGH' if score <= 19 else 'CRITICAL'
    return {'score': score, 'level': level}

