def key_strength(algorithm, bits):
    algo = algorithm.upper()
    if algo in ('DES', '3DES'):
        return 'WEAK'
    if algo == 'AES':
        if bits in (128, 192):
            return 'OK'
        if bits == 256:
            return 'STRONG'
        raise ValueError('invalid AES key size')
    if algo == 'RSA':
        return 'WEAK' if bits < 2048 else 'OK' if bits < 3072 else 'STRONG'
    if algo == 'ECC':
        return 'WEAK' if bits < 256 else 'OK' if bits < 384 else 'STRONG'
    raise ValueError('unknown algorithm')

