def hash_password(password, salt_hex, rounds):
    if rounds < 1000:
        raise ValueError('use at least 1000 rounds')
    pw = password.encode()
    h = hashlib.sha256(bytes.fromhex(salt_hex) + pw).digest()
    for _ in range(rounds - 1):
