def verify_jwt(token, secret, now):
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError('malformed token')
    h, p, s = parts
    if _decode(h).get('alg') != 'HS256':
        raise ValueError('bad alg')
    mac = hmac.new(secret.encode(), f'{h}.{p}'.encode(), hashlib.sha256).digest()
    expected = base64.urlsafe_b64encode(mac).rstrip(b'=').decode()
