def rbac_allowed(user_roles, permission, role_perms, parents):
    stack, seen = list(user_roles), set()
    while stack:
        role = stack.pop()
        if role in seen:
            continue
        seen.add(role)
        if permission in role_perms.get(role, set()):
            return True
        stack.extend(parents.get(role, []))
    return False

