def gateway(calls, capacity, rate):
    buckets, decisions = {}, []
    for t, client, url in calls:
        if not _ssrf_ok(url):
            decisions.append('BLOCKED_SSRF')
            continue
        tokens, last = buckets.get(client, (float(capacity), None))
        if last is not None:
            tokens = min(capacity, tokens + (t - last) * rate)
        if tokens >= 1:
            tokens -= 1
            decisions.append('ALLOW')
        else:
            decisions.append('RATE_LIMITED')
        buckets[client] = (tokens, t)
    return decisions

