class HandleTable:
    def __init__(self):
        self.objs, self.gens, self.alive, self.free = [], [], [], []

    def put(self, obj):
        if self.free:
            i = self.free.pop()
            self.gens[i] += 1
            self.objs[i], self.alive[i] = obj, True
        else:
            i = len(self.objs)
            self.objs.append(obj)
            self.gens.append(0)
            self.alive.append(True)
        return (i, self.gens[i])

    def _check(self, handle):
        i, gen = handle
        if not (0 <= i < len(self.objs)) or not self.alive[i] or self.gens[i] != gen:
            raise ValueError('stale handle')
        return i

    def get(self, handle):
        return self.objs[self._check(handle)]

    def remove(self, handle):
        i = self._check(handle)
        self.alive[i] = False
        self.objs[i] = None
        self.free.append(i)

