AV = {'N': 0.85, 'A': 0.62, 'L': 0.55, 'P': 0.2}
AC = {'L': 0.77, 'H': 0.44}
UI = {'N': 0.85, 'R': 0.62}
CIA = {'H': 0.56, 'L': 0.22, 'N': 0.0}


def _roundup(x):
    i = round(x * 100000)
    return i / 100000 if i % 10000 == 0 else (i // 10000 + 1) / 10


def cvss_base(m):
    changed = m['S'] == 'C'
    pr = {'N': 0.85, 'L': 0.68 if changed else 0.62, 'H': 0.5 if changed else 0.27}[m['PR']]
    iss = 1 - (1 - CIA[m['C']]) * (1 - CIA[m['I']]) * (1 - CIA[m['A']])
    impact = 7.52 * (iss - 0.029) - 3.25 * (iss - 0.02) ** 15 if changed else 6.42 * iss
    exploit = 8.22 * AV[m['AV']] * AC[m['AC']] * pr * UI[m['UI']]
    if impact <= 0:
        return 0.0
    total = 1.08 * (impact + exploit) if changed else impact + exploit
    return _roundup(min(total, 10))

REQUIRED = ['AV', 'AC', 'PR', 'UI', 'S', 'C', 'I', 'A']


def cvss_severity(vector, score):
    if not vector.startswith('CVSS:3.1/'):
        raise ValueError('only CVSS 3.1 vectors are supported')
    metrics = dict(p.split(':', 1) for p in vector.split('/')[1:] if ':' in p)
    if any(k not in metrics for k in REQUIRED):
        raise ValueError('missing metrics')
    if score == 0:
        rating = 'None'
    elif score < 4.0:
        rating = 'Low'
    elif score < 7.0:
        rating = 'Medium'
    elif score < 9.0:
        rating = 'High'
    else:
        rating = 'Critical'
    return metrics, rating

