    for i, (e, stored) in enumerate(zip(entries, hashes)):
        prev = hashlib.sha256((prev + e).encode()).hexdigest()
        if prev != stored:
            return i
    if len(entries) != len(hashes):
        return min(len(entries), len(hashes))
    return None

def triage(alerts, assets):
    ordered = sorted(alerts, key=lambda a: (-a['severity'] * assets.get(a['asset'], 1), -a['severity'], a['id']))
    return [a['id'] for a in ordered]

def scorecard(controls):
    score = round(sum(controls.values()) / len(controls) * 100, 1) if controls else 0.0
    grade = 'A' if score >= 90 else 'B' if score >= 75 else 'C' if score >= 50 else 'D'
    return {'score': score, 'grade': grade, 'gaps': sorted(k for k, v in controls.items() if not v)}
